<?php use App\Core\Http; ?>
<h1>Users</h1>
<table><tr><th>Name</th><th>Email</th><th>Role</th><th>Active</th><th></th></tr><?php foreach ($rows as $r): ?><tr><td><?= Http::e($r['name']) ?></td><td><?= Http::e($r['email']) ?></td><td><?= Http::e($r['role']) ?></td><td><?= $r['active'] ? 'yes' : 'no' ?></td><td><form method="post" action="/admin/users"><?= Http::csrfField() ?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= (int) $r['id'] ?>"><button class="ghost" type="submit">Enable/disable</button></form></td></tr><?php endforeach; ?></table>
